O=R/json.loads((D/'ACTIVE-v1.json').read_text())['receipt'];C=O/'AUDIT-CERTIFICATE-v2.json';c=json.loads(C.read_text());assert c['status']=='PASS_AUTHOR_ACTUAL_RECOVERY_SOURCE_UNIT_BIT_NATIVE_OPEN'
